/**
 * @param {number[][]} grid
 * @param {number} k
 * @return {number[][]}
 */
var shiftGrid = function(grid, k) {
    const m = grid.length;
    const n = grid[0].length;

    let arr = [];

    for (const row of grid) {
        arr.push(...row);
    }

    const cut = k % arr.length;
    arr = arr.slice(-cut).concat(arr.slice(0, -cut));

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            grid[i][j] = arr[n * i + j];
        }
    }

    return grid;
};
